import { test } from 'node:test';
import assert from 'node:assert/strict';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { entries, recordEntries, fillCharacterSimp } from '../sources/wiktionary-zh.js';
import { buildIndex } from '../build-index.js';
import { serializeIndex, deserializeIndex } from '../lib/index-format.js';
import { Dictionary } from '../lookup.js';

// 41 records of the kaikki.org Chinese extract, reduced to the fields the
// source reads (test/fixtures/wiktionary-zh.jsonl, regenerated by make-wiktionary-fixture.js).
const FIXTURE = resolve(dirname(fileURLToPath(import.meta.url)), 'fixtures', 'wiktionary-zh.jsonl');

async function all() {
  const out = [];
  for await (const e of entries(FIXTURE)) out.push(e);
  return out;
}

const find = (rows, trad, pinyin) => rows.filter((e) => e.trad === trad && (pinyin === undefined || e.pinyin === pinyin));

test('traditional title with its simplified form and numbered pinyin', async () => {
  const rows = await all();
  const [e] = find(rows, '學習');
  assert.deepEqual({ simp: e.simp, trad: e.trad, pinyin: e.pinyin }, { simp: '学习', trad: '學習', pinyin: 'xue2 xi2' });
  assert.match(e.definition, /^\(verb\) to study; to learn/);
  assert.deepEqual(find(rows, '你好').map((r) => r.pinyin), ['ni3 hao3']);
});

test('records of one page and reading are merged, part of speech kept per record', async () => {
  const rows = await all();
  const china = find(rows, '中國');
  assert.equal(china.length, 1);
  assert.equal(china[0].simp, '中国');
  assert.equal(china[0].pinyin, 'Zhong1 guo2');
  assert.match(china[0].definition, /^\(name\) China \(a country in Asia; capital: Beijing\)\//);
  assert.match(china[0].definition, /\/\(noun\) \(Classical\) royal court/);
});

test('soft redirects (simplified pages) produce no entry of their own', async () => {
  const rows = await all();
  assert.equal(rows.filter((e) => e.trad === '中国' || e.trad === '学习').length, 0);
});

test('one entry per distinct Standard Chinese reading, erhua and phonetic variants excluded', async () => {
  const rows = await all();
  assert.deepEqual(find(rows, '女').map((e) => e.pinyin), ['nü3', 'nü4', 'ru3']);
  assert.deepEqual(find(rows, '綠').map((e) => e.pinyin), ['lü4', 'lu4']);
  assert.deepEqual(find(rows, '一下').map((e) => e.pinyin), ['yi1 xia4']);
  assert.deepEqual(find(rows, '花兒').map((e) => e.pinyin), ['hua1 r5', 'hua1 er2']);
});

test('single characters get their simplified form from two-script word pairs', async () => {
  const rows = await all();
  assert.deepEqual([...new Set(find(rows, '發').map((e) => e.simp))], ['发'], 'from 發展 / 发展');
  assert.deepEqual([...new Set(find(rows, '綠').map((e) => e.simp))], ['绿'], 'from 綠色 / 绿色');
  assert.deepEqual([...new Set(find(rows, '女').map((e) => e.simp))], ['女'], 'unchanged when nothing maps it');
});

test('a character kept in most words is not remapped by one odd pair', () => {
  const list = [
    { trad: '律', simp: '律', pinyin: 'lu:4' },
    { trad: '律師', simp: '律师' },
    { trad: '法律', simp: '法律' },
    { trad: '律呂', simp: '侓吕' },
    { trad: '綠', simp: '綠' },
    { trad: '綠色', simp: '绿色' },
  ];
  fillCharacterSimp(list);
  assert.equal(list[0].simp, '律');
  assert.equal(list[4].simp, '绿');
});

test('a phonetic note in brackets does not leak into the reading', async () => {
  const rows = await all();
  assert.deepEqual(find(rows, '日本語').map((e) => e.pinyin), ['Ri4 ben3 yu3']);
  assert.ok(rows.every((e) => !/[[\]:]/.test(e.pinyin)), 'no bracket or colon in any pinyin');
});

test('a phrase reading split at its comma is put back together', async () => {
  const rows = await all();
  assert.deepEqual(find(rows, '人不像人，鬼不像鬼').map((e) => e.pinyin),
    ['ren2 bu4 xiang4 ren2 , gui3 bu4 xiang4 gui3']);
});

test('a record without a Mandarin reading keeps an entry with empty pinyin', async () => {
  const rows = await all();
  const [e] = find(rows, '昨日');
  assert.equal(e.pinyin, '');
  assert.equal(e.definition, '(noun) (Min) day before yesterday');
});

test('records without Hanzi or without a gloss are skipped', () => {
  assert.deepEqual(recordEntries({ word: 'van', pos: 'noun', senses: [{ glosses: ['a van'] }] }), []);
  assert.deepEqual(recordEntries({ word: '中', pos: 'character', senses: [{ tags: ['no-gloss'] }] }), []);
});

test('index built from the fixture answers pinyin, hanzi and English queries', async () => {
  const d = new Dictionary(deserializeIndex(serializeIndex(await buildIndex(entries(FIXTURE)))));
  assert.equal(d.search('nihao')[0].simp, '你好');
  assert.equal(d.search('zhongguo')[0].simp, '中国');
  assert.equal(d.search('学习')[0].trad, '學習');
  assert.equal(d.search('學習')[0].simp, '学习');
  assert.equal(d.search('lv4')[0].trad, '綠');
  assert.ok(d.search('绿').some((e) => e.trad === '綠'));
  assert.ok(d.search('/tobacco').some((e) => e.simp === '烟草'));
});
